-- Baseline schema for notification-service.
-- Squashed from all earlier migrations; equivalent to running them in order on an empty database.

CREATE TABLE `notifications` (
  `id` varchar(36) NOT NULL,
  `event_id` varchar(100) NOT NULL,
  `user_id` varchar(36) DEFAULT NULL,
  `event_type` varchar(100) NOT NULL,
  `channel` varchar(32) NOT NULL,
  `recipient` varchar(320) DEFAULT NULL,
  `template_code` varchar(150) NOT NULL,
  `payload` longtext NOT NULL,
  `status` varchar(32) NOT NULL,
  `attempt_count` int NOT NULL DEFAULT '0',
  `last_error` text,
  `created_at` timestamp(6) NOT NULL,
  `sent_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NOT NULL,
  `title` varchar(200) DEFAULT NULL,
  `message` text,
  `action_url` varchar(1000) DEFAULT NULL,
  `read_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_notifications_event_channel` (`event_id`,`channel`),
  KEY `idx_notifications_user_id` (`user_id`),
  KEY `idx_notifications_status` (`status`),
  KEY `idx_notifications_created_at` (`created_at`),
  KEY `idx_notifications_user_channel_created` (`user_id`,`channel`,`created_at`),
  KEY `idx_notifications_user_channel_read` (`user_id`,`channel`,`read_at`)
) ENGINE=InnoDB;

CREATE TABLE `notification_attempts` (
  `id` varchar(36) NOT NULL,
  `notification_id` varchar(36) NOT NULL,
  `attempt_number` int NOT NULL,
  `provider` varchar(100) NOT NULL,
  `status` varchar(32) NOT NULL,
  `provider_message_id` varchar(255) DEFAULT NULL,
  `error_code` varchar(100) DEFAULT NULL,
  `error_message` text,
  `created_at` timestamp(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_notification_attempts_notification_id` (`notification_id`),
  CONSTRAINT `fk_notification_attempts_notification` FOREIGN KEY (`notification_id`) REFERENCES `notifications` (`id`)
) ENGINE=InnoDB;

CREATE TABLE `notification_templates` (
  `id` varchar(36) NOT NULL,
  `template_code` varchar(150) NOT NULL,
  `channel` varchar(20) NOT NULL,
  `subject` varchar(500) DEFAULT NULL,
  `body` longtext NOT NULL,
  `version` int NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp(6) NOT NULL,
  `updated_at` timestamp(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code_channel_version` (`template_code`,`channel`,`version`),
  KEY `idx_template_code_channel` (`template_code`,`channel`)
) ENGINE=InnoDB;

-- Seed data: notification_templates (active = 1).
