INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('007248db-e054-11f1-a411-0af03e2234fb','ATTEMPT_SUBMITTED_EMAIL_V1','EMAIL','Test submitted - Baahubali','<html><body><h2>Test submitted</h2><p>Your attempt <strong>{{attemptId}}</strong> has been submitted successfully.</p><p>Test ID: {{testId}}</p></body></html>',1,1,'2026-11-14 17:51:21.454996','2026-11-14 17:51:21.454996');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('015f15b2-e054-11f1-a411-0af03e2234fb','PASSWORD_RESET_REQUESTED_EMAIL_V1','EMAIL','Reset your ClearIt password','<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Reset your ClearIt password</title>\n</head>\n\n<body style=\"\n    margin:0;\n    padding:0;\n    background:#f4f7fb;\n    font-family:Arial,Helvetica,sans-serif;\n    color:#1f2937;\n\">\n\n<table role=\"presentation\"\n       width=\"100%\"\n       cellspacing=\"0\"\n       cellpadding=\"0\"\n       border=\"0\"\n       style=\"background:#f4f7fb;padding:40px 16px;\">\n\n    <tr>\n        <td align=\"center\">\n\n            <table role=\"presentation\"\n                   width=\"100%\"\n                   cellspacing=\"0\"\n                   cellpadding=\"0\"\n                   border=\"0\"\n                   style=\"\n                       max-width:600px;\n                       background:#ffffff;\n                       border-radius:16px;\n                       overflow:hidden;\n                       box-shadow:0 4px 20px rgba(15,23,42,0.08);\n                   \">\n\n                <!-- Header -->\n                <tr>\n                    <td style=\"\n                        background:linear-gradient(135deg,#2563eb,#4f46e5);\n                        padding:32px 40px;\n                        text-align:center;\n                    \">\n\n                        <div style=\"\n                            font-size:30px;\n                            font-weight:800;\n                            color:#ffffff;\n                            letter-spacing:-0.5px;\n                        \">\n                            ClearIt\n                        </div>\n\n                        <div style=\"\n                            margin-top:8px;\n                            font-size:14px;\n                            color:#dbeafe;\n                        \">\n                            Your preparation starts here.\n                        </div>\n\n                    </td>\n                </tr>\n\n                <!-- Icon + Title -->\n                <tr>\n                    <td style=\"\n                        padding:42px 40px 10px;\n                        text-align:center;\n                    \">\n\n                        <div style=\"\n                            width:64px;\n                            height:64px;\n                            line-height:64px;\n                            margin:0 auto 20px;\n                            border-radius:50%;\n                            background:#eff6ff;\n                            color:#2563eb;\n                            font-size:30px;\n                            font-weight:bold;\n                        \">\n                            🔐\n                        </div>\n\n                        <h1 style=\"\n                            margin:0;\n                            font-size:26px;\n                            line-height:1.3;\n                            color:#111827;\n                        \">\n                            Reset your password\n                        </h1>\n\n                        <p style=\"\n                            margin:18px 0 0;\n                            font-size:16px;\n                            line-height:1.7;\n                            color:#6b7280;\n                        \">\n                            Hi {{firstName}},<br>\n                            We received a request to reset the password\n                            for your ClearIt account.\n                        </p>\n\n                    </td>\n                </tr>\n\n                <!-- CTA -->\n                <tr>\n                    <td style=\"\n                        padding:30px 40px 20px;\n                        text-align:center;\n                    \">\n\n                        <a href=\"{{resetUrl}}\"\n                           style=\"\n                               display:inline-block;\n                               background:#2563eb;\n                               color:#ffffff;\n                               text-decoration:none;\n                               font-size:16px;\n                               font-weight:700;\n                               padding:15px 30px;\n                               border-radius:10px;\n                               box-shadow:0 4px 10px rgba(37,99,235,0.25);\n                           \">\n                            Reset My Password →\n                        </a>\n\n                    </td>\n                </tr>\n\n                <!-- Expiry notice -->\n                <tr>\n                    <td style=\"\n                        padding:20px 40px 30px;\n                    \">\n\n                        <div style=\"\n                            background:#eff6ff;\n                            border-left:4px solid #2563eb;\n                            border-radius:8px;\n                            padding:16px 18px;\n                        \">\n\n                            <p style=\"\n                                margin:0;\n                                font-size:14px;\n                                line-height:1.6;\n                                color:#374151;\n                            \">\n\n                                <strong style=\"color:#1d4ed8;\">\n                                    This link expires in 15 minutes.\n                                </strong>\n\n                                <br>\n\n                                For your security, the password reset link\n                                can only be used once.\n\n                            </p>\n\n                        </div>\n\n                    </td>\n                </tr>\n\n                <!-- Fallback URL -->\n                <tr>\n                    <td style=\"\n                        padding:0 40px 34px;\n                    \">\n\n                        <p style=\"\n                            margin:0;\n                            font-size:13px;\n                            line-height:1.7;\n                            color:#9ca3af;\n                        \">\n                            If the button above does not work, copy and paste\n                            the following link into your browser:\n                        </p>\n\n                        <p style=\"\n                            margin:10px 0 0;\n                            word-break:break-all;\n                            font-size:13px;\n                            line-height:1.6;\n                        \">\n\n                            <a href=\"{{resetUrl}}\"\n                               style=\"color:#2563eb;text-decoration:none;\">\n                                {{resetUrl}}\n                            </a>\n\n                        </p>\n\n                    </td>\n                </tr>\n\n                <!-- Security notice -->\n                <tr>\n                    <td style=\"\n                        padding:0 40px 30px;\n                    \">\n\n                        <div style=\"\n                            background:#fff7ed;\n                            border-left:4px solid #f97316;\n                            border-radius:8px;\n                            padding:16px 18px;\n                        \">\n\n                            <p style=\"\n                                margin:0;\n                                font-size:13px;\n                                line-height:1.6;\n                                color:#7c2d12;\n                            \">\n\n                                <strong>Didn\'t request a password reset?</strong>\n\n                                <br>\n\n                                You can safely ignore this email.\n                                Your password will remain unchanged.\n\n                            </p>\n\n                        </div>\n\n                    </td>\n                </tr>\n\n                <!-- Footer -->\n                <tr>\n                    <td style=\"\n                        border-top:1px solid #e5e7eb;\n                        padding:24px 40px;\n                        text-align:center;\n                        background:#fafafa;\n                    \">\n\n                        <p style=\"\n                            margin:0;\n                            font-size:13px;\n                            color:#9ca3af;\n                        \">\n                            © 2026 ClearIt. All rights reserved.\n                        </p>\n\n                        <p style=\"\n                            margin:8px 0 0;\n                            font-size:12px;\n                            color:#d1d5db;\n                        \">\n                            This is an automated email. Please do not reply.\n                        </p>\n\n                    </td>\n                </tr>\n\n            </table>\n\n        </td>\n    </tr>\n\n</table>\n\n</body>\n</html>',1,1,'2026-11-14 17:51:23.007675','2026-11-14 17:51:23.007675');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('02159426-e054-11f1-a411-0af03e2234fb','ATTEMPT_SUBMITTED_IN_APP_V1','IN_APP','Test submitted successfully','Your test has been submitted successfully. View your result and review your performance.',1,1,'2026-11-14 17:51:24.203707','2026-11-14 17:51:24.203707');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('02159802-e054-11f1-a411-0af03e2234fb','PAYMENT_CAPTURED_IN_APP_V1','IN_APP','Payment successful','Your payment was successful! Your purchased test series is now ready to access.',1,1,'2026-11-14 17:51:24.203707','2026-11-14 17:51:24.203707');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('021598ba-e054-11f1-a411-0af03e2234fb','PAYMENT_CAPTURED_EMAIL_V1','EMAIL','Payment successful | ClearIt','<html><body><h2>Payment successful!</h2><p>Hi {{firstName}},</p><p>Your payment of <strong>{{amount}} {{currency}}</strong> has been received successfully.</p><p>Your purchased test series: <strong>{{seriesTitle}}</strong></p><p><a href=\"{{seriesUrl}}\">Access your test series</a></p><p><strong>Order ID:</strong> {{orderId}}</p><p>Thank you for choosing ClearIt. Happy learning!</p><p>Regards,<br>The ClearIt Team</p></body></html>',1,1,'2026-11-14 17:51:24.203707','2026-11-14 17:51:24.203707');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('02159961-e054-11f1-a411-0af03e2234fb','STREAK_AT_RISK_EMAIL_V1','EMAIL','Keep your learning streak alive | ClearIt','<html><body><h2>Your streak is waiting!</h2><p>Hi {{firstName}},</p><p>You have an opportunity to keep your learning streak going. Submit at least one test today to maintain your consistency.</p><p><a href=\"{{testsUrl}}\">Explore tests on ClearIt</a></p><p>Every attempt brings you one step closer to your goal. Keep going!</p><p>Regards,<br>The ClearIt Team</p></body></html>',1,1,'2026-11-14 17:51:24.203707','2026-11-14 17:51:24.203707');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('026346d6-e054-11f1-a411-0af03e2234fb','ACCESS_GRANTED_IN_APP_V1','IN_APP','New test series unlocked','You now have access to {{seriesTitle}}. Start practising whenever you are ready.',1,1,'2026-11-14 17:51:24.712519','2026-11-14 17:51:24.712519');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('02634b74-e054-11f1-a411-0af03e2234fb','ACCESS_GRANTED_EMAIL_V1','EMAIL','You now have access to {{seriesTitle}} | ClearIt','<html><body style=\"margin:0;padding:0;background:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9;padding:32px 12px;\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(15,23,42,0.06);\">\n<tr><td style=\"background:linear-gradient(135deg,#4f46e5,#7c3aed);background-color:#4f46e5;padding:28px 32px;\">\n<p style=\"margin:0;font-size:13px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:#e0e7ff;\">Access unlocked</p>\n<h1 style=\"margin:8px 0 0;font-size:24px;line-height:1.3;color:#ffffff;\">{{seriesTitle}}</h1>\n</td></tr>\n<tr><td style=\"padding:28px 32px 8px;\">\n<p style=\"margin:0 0 14px;font-size:16px;color:#0f172a;\">Hi {{firstName}},</p>\n<p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#334155;\">Good news! The ClearIt team has given you full access to <strong>{{seriesTitle}}</strong>. Every mock test in the series is now available in your account &mdash; no payment needed.</p>\n<p style=\"margin:0;font-size:15px;line-height:1.6;color:#334155;\">{{accessPeriod}}</p>\n{{reasonBlock}}\n</td></tr>\n<tr><td style=\"padding:24px 32px 32px;\">\n<a href=\"{{seriesUrl}}\" style=\"display:inline-block;background:#4f46e5;color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 24px;border-radius:10px;\">Start practising</a>\n<p style=\"margin:24px 0 0;font-size:14px;line-height:1.6;color:#64748b;\">All the best with your preparation!<br>The ClearIt Team</p>\n</td></tr>\n</table>\n<p style=\"margin:16px 0 0;font-size:12px;color:#94a3b8;\">You received this email because access was added to your ClearIt account.</p>\n</td></tr></table>\n</body></html>',1,1,'2026-11-14 17:51:24.712519','2026-11-14 17:51:24.712519');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('02c6ab23-e054-11f1-a411-0af03e2234fb','ACCESS_REVOKED_IN_APP_V1','IN_APP','Test series access removed','Your access to {{seriesTitle}} has been removed. Your past attempts and results are still in your history.',1,1,'2026-11-14 17:51:25.364222','2026-11-14 17:51:25.364222');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('02c6b0a2-e054-11f1-a411-0af03e2234fb','ACCESS_REVOKED_EMAIL_V1','EMAIL','Update on your access to {{seriesTitle}} | ClearIt','<html><body style=\"margin:0;padding:0;background:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9;padding:32px 12px;\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(15,23,42,0.06);\">\n<tr><td style=\"background-color:#334155;padding:28px 32px;\">\n<p style=\"margin:0;font-size:13px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:#cbd5e1;\">Access update</p>\n<h1 style=\"margin:8px 0 0;font-size:24px;line-height:1.3;color:#ffffff;\">{{seriesTitle}}</h1>\n</td></tr>\n<tr><td style=\"padding:28px 32px 8px;\">\n<p style=\"margin:0 0 14px;font-size:16px;color:#0f172a;\">Hi {{firstName}},</p>\n<p style=\"margin:0 0 14px;font-size:15px;line-height:1.6;color:#334155;\">We are letting you know that your access to <strong>{{seriesTitle}}</strong> has been removed from your ClearIt account. Tests in this series can no longer be started.</p>\n<p style=\"margin:0;font-size:15px;line-height:1.6;color:#334155;\">Don&rsquo;t worry &mdash; every attempt you have already made, along with your scores and solutions, stays in your test history.</p>\n{{reasonBlock}}\n</td></tr>\n<tr><td style=\"padding:24px 32px 32px;\">\n<a href=\"{{historyUrl}}\" style=\"display:inline-block;background:#4f46e5;color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 24px;border-radius:10px;\">View my test history</a>\n<p style=\"margin:20px 0 0;font-size:14px;line-height:1.6;color:#64748b;\">Think this is a mistake? <a href=\"{{supportUrl}}\" style=\"color:#4f46e5;font-weight:600;text-decoration:none;\">Contact our support team</a> and we will look into it. You can also <a href=\"{{seriesUrl}}\" style=\"color:#4f46e5;font-weight:600;text-decoration:none;\">view the series</a> at any time.</p>\n<p style=\"margin:20px 0 0;font-size:14px;line-height:1.6;color:#64748b;\">Regards,<br>The ClearIt Team</p>\n</td></tr>\n</table>\n<p style=\"margin:16px 0 0;font-size:12px;color:#94a3b8;\">You received this email because access on your ClearIt account changed.</p>\n</td></tr></table>\n</body></html>',1,1,'2026-11-14 17:51:25.364222','2026-11-14 17:51:25.364222');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('0325fcbc-e054-11f1-a411-0af03e2234fb','USER_EMAIL_VERIFICATION_OTP_REQUESTED_EMAIL_V1','EMAIL','{{otp}} is your ClearIt verification code','<!DOCTYPE html>\n<html lang=\"en\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"></head>\n<body style=\"margin:0;padding:0;background:#f4f7fb;font-family:Arial,Helvetica,sans-serif;color:#1f2937;\">\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background:#f4f7fb;padding:40px 16px;\">\n<tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"max-width:600px;background:#ffffff;border-radius:16px;overflow:hidden;\">\n<tr><td style=\"background:linear-gradient(135deg,#2563eb,#4f46e5);padding:32px 40px;text-align:center;\">\n<div style=\"font-size:30px;font-weight:800;color:#ffffff;\">ClearIt</div>\n<div style=\"margin-top:8px;font-size:14px;color:#dbeafe;\">Your preparation starts here.</div>\n</td></tr>\n<tr><td style=\"padding:42px 40px 12px;\">\n<h1 style=\"margin:0;text-align:center;font-size:26px;color:#111827;\">Verify your email, {{firstName}}</h1>\n<p style=\"margin:20px 0 0;text-align:center;font-size:16px;line-height:1.7;color:#6b7280;\">Enter this code on the verification screen to activate your ClearIt account.</p>\n</td></tr>\n<tr><td style=\"padding:20px 40px 30px;text-align:center;\">\n<div style=\"display:inline-block;background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:16px 28px;font-size:34px;font-weight:800;letter-spacing:10px;color:#1d4ed8;font-family:\'Courier New\',Courier,monospace;\">{{otp}}</div>\n</td></tr>\n<tr><td style=\"padding:0 40px 30px;\">\n<div style=\"background:#eff6ff;border-left:4px solid #2563eb;border-radius:8px;padding:16px 18px;\">\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\"><strong style=\"color:#1d4ed8;\">This code expires in {{expiresInMinutes}} minutes.</strong><br>Never share it with anyone. ClearIt will never ask you for this code.</p>\n</div>\n</td></tr>\n<tr><td style=\"border-top:1px solid #e5e7eb;padding:24px 40px;text-align:center;background:#fafafa;\">\n<p style=\"margin:0;font-size:13px;line-height:1.6;color:#9ca3af;\">Didn\'t create a ClearIt account?<br>You can safely ignore this email.</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>',1,1,'2026-11-14 17:51:25.988991','2026-11-14 17:51:25.988991');
INSERT INTO `notification_templates` (`id`, `template_code`, `channel`, `subject`, `body`, `version`, `active`, `created_at`, `updated_at`) VALUES ('0326033f-e054-11f1-a411-0af03e2234fb','ACCOUNT_DELETION_OTP_REQUESTED_EMAIL_V1','EMAIL','{{otp}} is your code to delete your ClearIt account','<!DOCTYPE html>\n<html lang=\"en\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"></head>\n<body style=\"margin:0;padding:0;background:#f4f7fb;font-family:Arial,Helvetica,sans-serif;color:#1f2937;\">\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background:#f4f7fb;padding:40px 16px;\">\n<tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"max-width:600px;background:#ffffff;border-radius:16px;overflow:hidden;\">\n<tr><td style=\"background:#334155;padding:32px 40px;text-align:center;\">\n<div style=\"font-size:30px;font-weight:800;color:#ffffff;\">ClearIt</div>\n<div style=\"margin-top:8px;font-size:14px;color:#cbd5e1;\">Account deletion request</div>\n</td></tr>\n<tr><td style=\"padding:42px 40px 12px;\">\n<h1 style=\"margin:0;text-align:center;font-size:26px;color:#111827;\">Confirm account deletion</h1>\n<p style=\"margin:20px 0 0;text-align:center;font-size:16px;line-height:1.7;color:#6b7280;\">Hi {{firstName}}, we received a request to permanently delete your ClearIt account. Enter this code to confirm.</p>\n</td></tr>\n<tr><td style=\"padding:20px 40px 30px;text-align:center;\">\n<div style=\"display:inline-block;background:#fef2f2;border:1px solid #fecaca;border-radius:12px;padding:16px 28px;font-size:34px;font-weight:800;letter-spacing:10px;color:#b91c1c;font-family:\'Courier New\',Courier,monospace;\">{{otp}}</div>\n</td></tr>\n<tr><td style=\"padding:0 40px 30px;\">\n<div style=\"background:#fef2f2;border-left:4px solid #dc2626;border-radius:8px;padding:16px 18px;\">\n<p style=\"margin:0;font-size:14px;line-height:1.6;color:#374151;\"><strong style=\"color:#b91c1c;\">This code expires in {{expiresInMinutes}} minutes.</strong><br>Deleting your account removes your profile and signs you out everywhere. This cannot be undone.</p>\n</div>\n</td></tr>\n<tr><td style=\"border-top:1px solid #e5e7eb;padding:24px 40px;text-align:center;background:#fafafa;\">\n<p style=\"margin:0;font-size:13px;line-height:1.6;color:#9ca3af;\">Didn\'t ask to delete your account?<br>Ignore this email and consider changing your password.</p>\n</td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>',1,1,'2026-11-14 17:51:25.988991','2026-11-14 17:51:25.988991');
